// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint8 actorSeed) public {
        address actor = address(uint160(actorSeed) + 1);
        vm.assume(actor != address(0) && depositAmount > 0 && depositAmount <= type(uint256).max / 2);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        uint256 userBalanceBefore = c.getBalance(actor);

        vm.prank(actor);
        bool ok = true;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;
        uint256 userBalanceAfter = c.getBalance(actor);

        if (ok) {
            assertTrue(balanceAfter <= balanceBefore - userBalanceBefore);
        } else {
            assertTrue(balanceBefore == balanceAfter || userBalanceBefore != userBalanceAfter);
        }
    }
}
